import { Component, createUniqueId, mergeProps } from 'solid-js';
import type { InputDateVariantProps } from '../input.types';
import { DEFAULT_PROPS } from '../input.utils';
import { InputText } from './input-text';

export const InputDate: Component<InputDateVariantProps> = (p => {
  const id = createUniqueId();
  p = mergeProps({ ...DEFAULT_PROPS, id }, p);
  return (
    <InputText
      {...p}
      nativeType="date"
      typeOrigin="date"
      maskOptions={void 0}
      allowClear={false}
    />
  );
}) as Component<InputDateVariantProps>;
